// UserServiceServer is the server API for UserService service.
// All implementations must embed UnimplementedUserServiceServer
// for forward compatibility.
type UserServiceServer interface {
	GetOrCreateByEmail(context.Context, *GetOrCreateByEmailRequest) (*GetOrCreateByEmailResponse, error)
	// Requires an access token; works on the caller's own account.
	GetMe(context.Context, *GetMeRequest) (*GetMeResponse, error)
	UpdateProfile(context.Context, *UpdateProfileRequest) (*UpdateProfileResponse, error)
	// The status alone, as openvk edits it on the page.
	UpdateStatus(context.Context, *UpdateStatusRequest) (*UpdateStatusResponse, error)
	// The address of the page alone ("Адрес страницы" of the settings); the
	// profile has to be filled first.
	UpdateNickname(context.Context, *UpdateNicknameRequest) (*UpdateNicknameResponse, error)
	UpdatePrivacy(context.Context, *UpdatePrivacyRequest) (*UpdatePrivacyResponse, error)
	// "Интерфейс" of the settings: how the site looks to the caller alone.
	UpdateInterface(context.Context, *UpdateInterfaceRequest) (*UpdateInterfaceResponse, error)
	// openvk's "Контакты", "Интересы" and "Дополнительно" of the page; each
	// replaces its part at once.
	UpdateContacts(context.Context, *UpdateContactsRequest) (*UpdateContactsResponse, error)
	UpdateInterests(context.Context, *UpdateInterestsRequest) (*UpdateInterestsResponse, error)
	UpdateExtraFields(context.Context, *UpdateExtraFieldsRequest) (*UpdateExtraFieldsResponse, error)
	// Points the caller's profile to a photo uploaded to the media service;
	// an empty avatar_id removes the photo.
	SetAvatar(context.Context, *SetAvatarRequest) (*SetAvatarResponse, error)
	// Shows a photo the media service keeps under the caller on one side of
	// their page ("Фон страницы"), the other side as it is; an empty
	// photo_id clears the side. Tells which photo the side showed before,
	// for the caller to delete.
	SetBackdrop(context.Context, *SetBackdropRequest) (*SetBackdropResponse, error)
	// Public: returns only what other users may see.
	GetProfile(context.Context, *GetProfileRequest) (*GetProfileResponse, error)
	// Public: several profiles at once, e.g. the authors of a news feed.
	GetProfiles(context.Context, *GetProfilesRequest) (*GetProfilesResponse, error)
	// Public: people with a filled-in profile by name, surname or nickname.
	SearchUsers(context.Context, *SearchUsersRequest) (*SearchUsersResponse, error)
	// Require an access token; the follower is the caller. Idempotent.
	Follow(context.Context, *FollowRequest) (*emptypb.Empty, error)
	Unfollow(context.Context, *UnfollowRequest) (*emptypb.Empty, error)
	// Requires an access token: whom the caller follows, for the news feed.
	ListFollowingIDs(context.Context, *ListFollowingIDsRequest) (*ListFollowingIDsResponse, error)
	// Public. With an access token GetFollowStats also tells whether the
	// caller follows the user.
	GetFollowStats(context.Context, *GetFollowStatsRequest) (*GetFollowStatsResponse, error)
	ListFollowers(context.Context, *ListFollowsRequest) (*ListFollowsResponse, error)
	ListFollowing(context.Context, *ListFollowsRequest) (*ListFollowsResponse, error)
	// Requires an access token: the caller is on the site now ("Онлайн").
	MarkOnline(context.Context, *MarkOnlineRequest) (*emptypb.Empty, error)
	// Public: how many people the site has and how many are on it now, for
	// its page "о сайте".
	GetStatistics(context.Context, *GetStatisticsRequest) (*GetStatisticsResponse, error)
	// Requires an access token: whether the caller may write on the user's
	// wall, as the user's privacy and blacklists allow.
	CanPostOnWall(context.Context, *CanPostOnWallRequest) (*CanPostOnWallResponse, error)
	// Requires an access token: whether the caller may write private
	// messages to the user, as the user's privacy and blacklists allow.
	CanMessage(context.Context, *CanMessageRequest) (*CanMessageResponse, error)
	// Requires an access token: who of the people a text of the caller
	// names by nickname hears of it ("Вас упомянул пользователь" of
	// openvk): not the caller, not across a blacklist, not a deleted page.
	ResolveMentions(context.Context, *ResolveMentionsRequest) (*ResolveMentionsResponse, error)
	// Requires an access token: the people the caller names by nickname to
	// add to a group chat, and whether each lets the caller do it, as their
	// privacy and blacklists allow.
	ResolveInvites(context.Context, *ResolveInvitesRequest) (*ResolveInvitesResponse, error)
	// Public: which of the nicknames are someone's, so that a text saying
	// "@word" links to a page only when there is one.
	FindNicknames(context.Context, *FindNicknamesRequest) (*FindNicknamesResponse, error)
	// Public: what of the user's page the caller, anonymous without a token,
	// may see, as the user's privacy allows.
	GetAccess(context.Context, *GetAccessRequest) (*GetAccessResponse, error)
	// Require an access token: the caller's blacklist ("Чёрный список"). A
	// block shuts messages, wall posts and follows between the two, both
	// ways, and drops their follows. Block and Unblock are idempotent.
	Block(context.Context, *BlockRequest) (*emptypb.Empty, error)
	Unblock(context.Context, *UnblockRequest) (*emptypb.Empty, error)
	ListBlocked(context.Context, *ListBlockedRequest) (*ListBlockedResponse, error)
	// Requires an access token: whom the caller blacklisted, for the news
	// feed, which leaves their posts out.
	ListBlockedIDs(context.Context, *ListBlockedIDsRequest) (*ListBlockedIDsResponse, error)
	// Requires an access token. "Игнорируемые источники" of openvk: the
	// walls whose posts the caller's news feeds leave out. A source is a
	// user or a community — the caller checks that it is there. Both are
	// idempotent.
	IgnoreSource(context.Context, *IgnoreSourceRequest) (*emptypb.Empty, error)
	UnignoreSources(context.Context, *UnignoreSourcesRequest) (*emptypb.Empty, error)
	ListIgnoredSources(context.Context, *ListIgnoredSourcesRequest) (*ListIgnoredSourcesResponse, error)
	// Requires an access token: who of the caller and the user blacklisted
	// the other.
	GetRelation(context.Context, *GetRelationRequest) (*GetRelationResponse, error)
	// Gifts ("Подарки" on openvk). GetGiftCatalog is public: what there is
	// to send. SendGift sends one to a user: PermissionDenied if the page
	// is deleted, does not show itself to the caller or the two are
	// blacklisted either way. ListGifts is public: the gifts sent to a
	// user, newest first; PermissionDenied if the page or its gifts are
	// hidden from the caller. DeleteGift is for the one the gift was sent
	// to.
	GetGiftCatalog(context.Context, *GetGiftCatalogRequest) (*GetGiftCatalogResponse, error)
	SendGift(context.Context, *SendGiftRequest) (*SendGiftResponse, error)
	ListGifts(context.Context, *ListGiftsRequest) (*ListGiftsResponse, error)
	DeleteGift(context.Context, *DeleteGiftRequest) (*emptypb.Empty, error)
	// Votes ("голоса" on openvk) pay for the gifts that have a price.
	// TransferVotes hands some of the caller's to a user ("Перевод
	// голосов"): PermissionDenied to a deleted page and across a blacklist,
	// FailedPrecondition when the caller has fewer. RedeemVoucher gives the
	// caller what a voucher carries, once: FailedPrecondition whatever is
	// wrong with the voucher.
	TransferVotes(context.Context, *TransferVotesRequest) (*TransferVotesResponse, error)
	RedeemVoucher(context.Context, *RedeemVoucherRequest) (*RedeemVoucherResponse, error)
	// Vouchers are made by the administrators of the site (ADMIN_EMAILS):
	// PermissionDenied to anyone else.
	CreateVoucher(context.Context, *CreateVoucherRequest) (*CreateVoucherResponse, error)
	ListVouchers(context.Context, *ListVouchersRequest) (*ListVouchersResponse, error)
	DeleteVoucher(context.Context, *DeleteVoucherRequest) (*emptypb.Empty, error)
	// Require an access token: deleting the caller's page ("Удаление
	// страницы" on openvk) and restoring it. A deleted page is hidden: others
	// see only its name and photo, nobody may follow it, write on its wall
	// or to it. Its owner may restore it until purge_at, when its data is
	// erased in every service. The access tokens of a deleted page work only
	// for GetMe and ReactivateAccount; on public methods they are anonymous.
	DeactivateAccount(context.Context, *DeactivateAccountRequest) (*DeactivateAccountResponse, error)
	ReactivateAccount(context.Context, *ReactivateAccountRequest) (*ReactivateAccountResponse, error)
	// Internal (auth): whether the page is deleted, for the access tokens
	// it issues; NotFound once its data is erased.
	GetAccountState(context.Context, *GetAccountStateRequest) (*GetAccountStateResponse, error)
	mustEmbedUnimplementedUserServiceServer()
}

